changeSet.sql:
SET LOCAL lock_timeout = '5s';
LOCK TABLE nexus.catalog_collections, nexus.chunks, nexus.catalog_document_chunks,
           nexus.catalog_documents IN ACCESS EXCLUSIVE MODE;

ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY;
DO $$ DECLARE v_branch_a_count BIGINT; v_branch_b_count BIGINT; v_branch_c_count BIGINT; v_unseeded_tokens TEXT; BEGIN -- Candidates: exactly hygiene-002-1's branch-D signature (see this -- changeset's header for why that signature alone identifies "the old, -- narrower owner grammar failed to match this row"), re-matched against -- the WIDENED owner grammar [a-zA-Z0-9-]+(?:_[a-zA-Z0-9-]+)* -- a -- single underscore is legal only BETWEEN two alnum/hyphen tokens; a -- bare "__" can never appear inside the owner group itself, since that -- stays reserved, unconditionally, for the segment separator (FIX -- ROUND, this changeset's header note above -- removes the m2/m4 -- ambiguity at the grammar rather than relying on branch C's -- precedence guard below to arbitrate it). CREATE TEMP TABLE _h004_walk ON COMMIT DROP AS SELECT c.tenant_id, c.name, regexp_match(c.name, '^(code|docs|rdr|knowledge)__([a-zA-Z0-9-]+(?:_[a-zA-Z0-9-]+)*)__([a-z][a-z0-9-]*)__v[0-9]+$') AS m4, regexp_match(c.name, '^quarantine-(code|docs|rdr|knowledge)__([a-zA-Z0-9-]+(?:_[a-zA-Z0-9-]+)*)__([a-z][a-z0-9-]*)__v[0-9]+$') AS mq, regexp_match(c.name, '^(code|docs|rdr|knowledge)__([a-zA-Z0-9-]+(?:_[a-zA-Z0-9-]+)*)$') AS m2, (SELECT count(DISTINCT s.dim) FROM nexus.collection_vector_stats s WHERE s.tenant_id = c.tenant_id AND s.collection = c.name) AS stats_dim_count, (SELECT min(s.dim) FROM nexus.collection_vector_stats s WHERE s.tenant_id = c.tenant_id AND s.collection = c.name) AS stats_dim FROM nexus.catalog_collections c WHERE c.lifecycle_state = 'disputed' AND c.content_type = 'unknown' AND c.owner_id = c.tenant_id;
-- Branch A: 4-segment conformant names, widened owner grammar. UPDATE nexus.catalog_collections c SET content_type = w.m4[1], owner_id = w.m4[2], embedding_model = CASE WHEN em.embedding_model IS NOT NULL THEN w.m4[3] ELSE 'bge-base-en-v15-768' END, dimension = CASE WHEN w.stats_dim_count = 1 THEN w.stats_dim ELSE NULL END, lifecycle_state = CASE WHEN em.embedding_model IS NULL THEN 'disputed' WHEN w.stats_dim_count = 0 THEN 'live' WHEN w.stats_dim_count = 1 AND em.dimension = w.stats_dim THEN 'live' ELSE 'disputed' END FROM _h004_walk w LEFT JOIN nexus.embedding_models em ON em.embedding_model = w.m4[3] WHERE c.tenant_id = w.tenant_id AND c.name = w.name AND w.m4 IS NOT NULL; GET DIAGNOSTICS v_branch_a_count = ROW_COUNT; RAISE NOTICE 'hygiene-004-1: branch A (4-segment, widened owner grammar) re-filed % row(s)', v_branch_a_count;
-- Branch B: quarantine-CT__owner__model__vN, widened owner grammar -- -- lifecycle_state is ALWAYS 'quarantine', same as hygiene-002-1. UPDATE nexus.catalog_collections c SET content_type = w.mq[1], owner_id = w.mq[2], embedding_model = CASE WHEN em.embedding_model IS NOT NULL THEN w.mq[3] ELSE 'bge-base-en-v15-768' END, dimension = CASE WHEN w.stats_dim_count = 1 THEN w.stats_dim ELSE NULL END, lifecycle_state = 'quarantine' FROM _h004_walk w LEFT JOIN nexus.embedding_models em ON em.embedding_model = w.mq[3] WHERE c.tenant_id = w.tenant_id AND c.name = w.name AND w.mq IS NOT NULL; GET DIAGNOSTICS v_branch_b_count = ROW_COUNT; RAISE NOTICE 'hygiene-004-1: branch B (quarantine, widened owner grammar) re-filed % row(s)', v_branch_b_count;
-- Branch C: grandfathered 2-segment CT__owner, widened owner grammar -- -- nexus.embedding_profile is still empty for every tenant at this point -- in the changelog, same as hygiene-002-1's own branch C. -- -- PRECEDENCE GUARD (AND w.m4 IS NULL AND w.mq IS NULL) -- NOW -- UNREACHABLE, kept only as defense-in-depth and as a record of the -- exposure the FIX ROUND above closed at the grammar itself. -- Originally added because the FIRST widened grammar -- ([a-zA-Z0-9_-]+, unrestricted -- see this changeset's header FIX -- ROUND note) let a "_" appear anywhere, including immediately -- adjacent to another "_": m2's owner group, which has no trailing -- anchor, could then absorb straight through a genuine "__model__vN" -- suffix to the end of the string, making m2 ALSO match a name m4 or -- mq already matched correctly (e.g. under that FIRST grammar, -- "code__agree_owner__voyage-code-3__v1" satisfied m2 with owner_id = -- "agree_owner__voyage-code-3__v1" -- clearly wrong). The CURRENT -- grammar, [a-zA-Z0-9-]+(?:_[a-zA-Z0-9-]+)*, structurally forbids a -- bare "__" from ever appearing inside an owner segment (a "_" is -- legal only singly, between two alnum/hyphen tokens), so m2's owner -- group can no longer cross a literal "__" at all -- exactly the same -- structural guarantee hygiene-002-1's own narrow [a-zA-Z0-9-]+ owner -- class already had, and for the same reason: neither grammar has a -- legal way to spell "__" inside the owner. m4 and mq are therefore -- ALWAYS disjoint from m2 again, this guard can never fire, and it is -- retained rather than deleted so a future re-widening of the owner -- grammar does not silently reopen this exposure without a reviewer -- seeing why the guard exists. Branch A and B need no such guard in -- the other direction: their own trailing "__model__vN" anchor means -- a genuinely 2-segment name (which has no such suffix) never -- satisfies m4 or mq to begin with, and mq/m4 can never both match -- (disjoint on the literal "quarantine-" prefix). UPDATE nexus.catalog_collections c SET content_type = w.m2[1], owner_id = w.m2[2], embedding_model = COALESCE(ep.embedding_model, 'bge-base-en-v15-768'), dimension = CASE WHEN w.stats_dim_count = 1 THEN w.stats_dim ELSE NULL END, lifecycle_state = CASE WHEN w.stats_dim_count = 0 THEN 'live' WHEN w.stats_dim_count = 1 AND ep.embedding_model IS NOT NULL AND ep.dimension = w.stats_dim THEN 'live' ELSE 'disputed' END FROM _h004_walk w LEFT JOIN nexus.embedding_profile ep ON ep.tenant_id = w.tenant_id AND ep.content_type = w.m2[1] WHERE c.tenant_id = w.tenant_id AND c.name = w.name AND w.m2 IS NOT NULL AND w.m4 IS NULL AND w.mq IS NULL; GET DIAGNOSTICS v_branch_c_count = ROW_COUNT; RAISE NOTICE 'hygiene-004-1: branch C (grandfathered 2-segment, widened owner grammar) re-filed % row(s)', v_branch_c_count;
-- Census of re-filed rows whose name carries a model token this install -- does not recognise -- same courtesy notice as hygiene-002-1's own. SELECT string_agg(DISTINCT tok, ', ') INTO v_unseeded_tokens FROM ( SELECT (w.m4)[3] AS tok FROM _h004_walk w WHERE w.m4 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.embedding_models em WHERE em.embedding_model = (w.m4)[3]) UNION SELECT (w.mq)[3] AS tok FROM _h004_walk w WHERE w.mq IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.embedding_models em WHERE em.embedding_model = (w.mq)[3]) ) unseeded; IF v_unseeded_tokens IS NOT NULL THEN RAISE NOTICE 'hygiene-004-1: unseeded model token(s) found among re-filed collection names, backfilled to bge-base-en-v15-768 instead: %', v_unseeded_tokens; END IF; END $$;
ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_document_chunks FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_collections FORCE ROW LEVEL SECURITY;
